// WF-01 Node 2: Trích xuất, làm sạch IP và thông tin mạng
try {
  const input = $input.first().json;
  const raw = input.body?.data || input.body || input.data || input;

  let ip = String(raw.ip || raw.clientIp || raw.remoteAddress || '127.0.0.1').trim();
  if (ip.startsWith('::ffff:')) {
    ip = ip.replace('::ffff:', '');
  }
  if (ip === '::1' || ip === 'localhost') {
    ip = '127.0.0.1';
  }

  const email = String(raw.email || raw.targetEmail || 'unknown@company.com').toLowerCase().trim();
  const userAgent = String(raw.userAgent || raw.headers?.['user-agent'] || 'Unknown-Device').substring(0, 150);
  const reason = String(raw.reason || 'LOGIN_FAILED').trim();

  // Xác định Role mục tiêu (Ưu tiên role từ backend; nếu là user thông thường thì suy luận từ email)
  let targetRole = String(raw.targetRole || raw.role || '').toUpperCase();
  if (!targetRole || targetRole === 'USER' || targetRole === 'EMPLOYEE') {
    if (email.includes('superadmin') || email.includes('admin')) {
      targetRole = 'SUPERADMIN';
    } else if (email.includes('hr')) {
      targetRole = 'HR';
    } else if (email.includes('manager')) {
      targetRole = 'MANAGER';
    } else {
      targetRole = 'EMPLOYEE';
    }
  }

  const failedAttempts = Number(raw.failedAttempts || raw.attempts || 1);
  const timestamp = raw.timestamp || new Date().toISOString();
  const firstAttempt = raw.firstAttempt || timestamp;
  const isPrivilegedTarget = ['SUPERADMIN', 'HR', 'ADMIN'].includes(targetRole);

  return [{
    json: {
      ip,
      email,
      userAgent,
      reason,
      targetRole,
      failedAttempts,
      firstAttempt,
      timestamp,
      isPrivilegedTarget
    }
  }];
} catch (err) {
  throw new Error('[WF-01 Sanitize] Error: ' + err.message);
}

// WF-01 Node 3: Bộ đếm tần suất thất bại trong sliding window 15 phút
const item = $input.first().json;
const attempts = Number(item.failedAttempts !== undefined ? item.failedAttempts : 5);
const detectionWindowMinutes = 15;

// 1. Kiểm tra thời gian: Đo lường khoảng cách từ lần thử đầu tiên đến hiện tại
const eventTime = item.timestamp ? new Date(item.timestamp).getTime() : Date.now();
const firstAttemptTime = item.firstAttempt ? new Date(item.firstAttempt).getTime() : eventTime;
const elapsedMinutes = Math.max(0, Math.round((eventTime - firstAttemptTime) / (60 * 1000)));

// Điều kiện 1: Tần suất đăng nhập phải diễn ra trong khung trượt 15 phút (Sliding Window)
const isWithinWindow = elapsedMinutes <= detectionWindowMinutes;

// Điều kiện 2: Đạt ngưỡng tối thiểu 5 lần đăng nhập thất bại
const threshold = 5;

// Thỏa mãn đồng thời cả 2 điều kiện: Đúng 5 lần và xảy ra trong vòng 15 phút
const isThresholdReached = (attempts >= threshold) && isWithinWindow;

return [{
  json: {
    ...item,
    failedAttempts: attempts,
    threshold,
    detectionWindowMinutes,
    elapsedMinutes,
    isWithinWindow,
    isThresholdReached
  }
}];

// WF-01 Node 5: Tính thời gian khóa IP
const item = $input.first().json;
// SUPERADMIN/HR: phong tỏa 24 giờ (1440 phút). Employee: phong tỏa 60 phút
const banMinutes = item.isPrivilegedTarget ? 1440 : 60;
const banUntil = new Date(Date.now() + banMinutes * 60 * 1000).toISOString();
const incidentId = 'INC-BRUTE-' + Date.now().toString(36).toUpperCase();

return [{
  json: {
    ...item,
    incidentId,
    banMinutes,
    banUntil,
    banAction: 'TEMPORARY_IP_BLOCK'
  }
}];

// WF-01 Node 7: Gemini AI Threat Classifier (Hybrid AI Engine)
const input = $input.first().json;
// Trích xuất an toàn từ response backend (nếu bị bọc trong { data: ... }) hoặc từ input trực tiếp
const blockData = input.data || input;
let node5 = {};
try {
  node5 = $('5. Calc Ban Window & Incident ID').first().json || {};
} catch (e) {
  node5 = {};
}

const ip = blockData.ip || node5.ip || '127.0.0.1';
const email = blockData.email || node5.email || 'superadmin@company.com';
const failedAttempts = Number(blockData.failedAttempts !== undefined ? blockData.failedAttempts : (node5.failedAttempts !== undefined ? node5.failedAttempts : 5));
const targetRole = String(node5.targetRole || blockData.targetRole || (email.includes('superadmin') ? 'SUPERADMIN' : (email.includes('hr') ? 'HR' : 'EMPLOYEE'))).toUpperCase();
const isPrivileged = Boolean(node5.isPrivilegedTarget || ['SUPERADMIN', 'HR', 'ADMIN'].includes(targetRole));
const incidentId = blockData.incidentId || node5.incidentId || ('INC-BRUTE-' + Date.now().toString(36).toUpperCase());
const banMinutes = Number(blockData.banMinutes || node5.banMinutes || (isPrivileged ? 1440 : 60));
const banUntil = blockData.banUntil || node5.banUntil || new Date(Date.now() + banMinutes * 60 * 1000).toISOString();
const timestamp = node5.timestamp || blockData.timestamp || new Date().toISOString();

// 1. Tính toán điểm số đe dọa đa biến (Multi-Factor Threat Scoring)
const roleWeight = isPrivileged ? 40 : 15;
const attemptWeight = Math.min(failedAttempts * 12, 50);
const threatScore = Math.min(roleWeight + attemptWeight, 98);
const riskTier = threatScore >= 70 ? 'CRITICAL_ATTACK' : 'HIGH_SUSPICIOUS';
const attackType = failedAttempts >= 5 ? 'CREDENTIAL_STUFFING_BRUTEFORCE' : 'REPEATED_AUTH_FAILURE';

// 2. Gọi Google Gemini AI nếu có GEMINI_API_KEY
let geminiApiKey = '';
try {
  geminiApiKey = (typeof $env !== 'undefined' && $env.GEMINI_API_KEY) ? $env.GEMINI_API_KEY : '';
} catch (e) {
  geminiApiKey = '';
}
let aiAssessment = '';
let aiModelUsed = 'DevSecOps Heuristic Threat Engine v2.4';

if (geminiApiKey) {
  try {
    const prompt = `Bạn là Chuyên gia An ninh Thông tin (DevSecOps Lead) của hệ thống HR Tech Enterprise.
Hãy phân tích sự cố an ninh sau và đưa ra nhận định chuyên môn ngắn gọn trong 2 câu:
- IP nguồn: ${ip}
- Tài khoản mục tiêu: ${email} (Vai trò: ${targetRole})
- Số lần thử sai liên tiếp: ${failedAttempts} lần trong khung giờ giám sát
- Điểm đe dọa: ${threatScore}/100 (${riskTier})
Đưa ra kết luận về bản chất cuộc tấn công và khuyến nghị hành động tức thì cho đội ứng cứu sự cố.`;

    const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${geminiApiKey}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.2, maxOutputTokens: 150 }
      })
    });

    if (response.ok) {
      const resData = await response.json();
      aiAssessment = resData.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
      if (aiAssessment) {
        aiModelUsed = 'Google Gemini 2.5 Flash';
      }
    }
  } catch (apiErr) {
    // Tự động chuyển tiếp fallback nếu mạng chập chờn
  }
}

// 3. Fallback chuyên sâu phân theo ma trận rủi ro nếu chưa có API Key
if (!aiAssessment) {
  aiAssessment = isPrivileged
    ? `[BÁO ĐỘNG ĐỎ - Điểm đe dọa ${threatScore}/100]: Phát hiện tấn công dò mật khẩu có chủ đích (${attackType}) nhắm vào tài khoản quản trị cấp cao [${targetRole}]. Hệ thống đã kích hoạt cơ chế tự vệ phong tỏa IP [${ip}] trong ${banMinutes} phút và cảnh báo khẩn cấp tới DevSecOps.`
    : `[CẢNH BÁO VÀNG - Điểm đe dọa ${threatScore}/100]: Tần suất đăng nhập thất bại bất thường (${failedAttempts} lần/15 phút). Đã tạm thời cô lập IP [${ip}] trong ${banMinutes} phút để ngăn ngừa rủi ro tự động hóa dò quét.`;
}

return [{
  json: {
    ip,
    email,
    targetRole,
    failedAttempts,
    banMinutes,
    banUntil,
    incidentId,
    timestamp,
    threatScore,
    riskTier,
    attackType,
    aiAssessment,
    aiModel: aiModelUsed,
    analyzedAt: new Date().toISOString()
  }
}];

